create table if not exists public.review_amenity_feedback (id uuid primary key default gen_random_uuid(), review_id uuid not null references public.reviews(id) on delete cascade, location_id uuid not null references public.locations(id) on delete cascade, amenity_id uuid not null references public.amenities(id) on delete cascade, sentiment text not null check (sentiment in ('good','needs_attention')), created_at timestamptz not null default now(), unique(review_id,amenity_id)); create index if not exists idx_review_amenity_feedback_location on public.review_amenity_feedback(location_id); create index if not exists idx_review_amenity_feedback_amenity on public.review_amenity_feedback(amenity_id); create or replace function public.set_location_amenities(p_location_id uuid,p_amenity_ids uuid[]) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare v_business uuid; begin if auth.uid() is null then raise exception 'Authentication required'; end if; select business_id into v_business from locations where id=p_location_id; if v_business is null then raise exception 'Location not found'; end if; if not (exists(select 1 from business_members bm where bm.business_id=v_business and bm.user_id=auth.uid() and lower(bm.role) in ('owner','admin')) or lower(coalesce((select email from auth.users where id=auth.uid()),''))='matthagersr@gmail.com') then raise exception 'Business admin permission required'; end if; delete from location_amenities where location_id=p_location_id; insert into location_amenities(location_id,amenity_id) select p_location_id,a from unnest(coalesce(p_amenity_ids,'{}'::uuid[])) a on conflict do nothing; return jsonb_build_object('location_id',p_location_id,'amenity_ids',coalesce(p_amenity_ids,'{}'::uuid[])); end; $$; create or replace function public.record_review_amenity_feedback(p_review_id uuid,p_good_amenity_ids uuid[],p_attention_amenity_ids uuid[]) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare v_location uuid; begin if auth.uid() is null then raise exception 'Authentication required'; end if; select location_id into v_location from reviews where id=p_review_id and user_id=auth.uid(); if v_location is null then raise exception 'Review not found or not owned by current user'; end if; delete from review_amenity_feedback where review_id=p_review_id; insert into review_amenity_feedback(review_id,location_id,amenity_id,sentiment) select p_review_id,v_location,a,'good' from unnest(coalesce(p_good_amenity_ids,'{}'::uuid[])) a where not (a=any(coalesce(p_attention_amenity_ids,'{}'::uuid[]))) on conflict do nothing; insert into review_amenity_feedback(review_id,location_id,amenity_id,sentiment) select p_review_id,v_location,a,'needs_attention' from unnest(coalesce(p_attention_amenity_ids,'{}'::uuid[])) a on conflict do nothing; return jsonb_build_object('review_id',p_review_id,'recorded',true); end; $$; create or replace function public.business_amenity_feedback_analytics(p_business_id uuid,p_location_id uuid default null,p_start timestamptz default now()-interval '30 days',p_end timestamptz default now()) returns jsonb language sql security definer set search_path=public,pg_temp as $$ select coalesce(jsonb_agg(x order by x.category,x.amenity),'[]'::jsonb) from (select a.id amenity_id,a.name amenity,a.category,coalesce(sum((f.sentiment='good')::int),0) good_count,coalesce(sum((f.sentiment='needs_attention')::int),0) needs_attention_count,count(f.id) total_feedback from amenities a left join review_amenity_feedback f on f.amenity_id=a.id and f.created_at between p_start and p_end left join locations l on l.id=f.location_id and l.business_id=p_business_id and (p_location_id is null or l.id=p_location_id) where exists(select 1 from location_amenities la join locations l2 on l2.id=la.location_id where la.amenity_id=a.id and l2.business_id=p_business_id and (p_location_id is null or l2.id=p_location_id) and (f.location_id is null or f.location_id=l2.id)) group by a.id,a.name,a.category) x; $$;
